   427→					clearScroll.addScrollId(scrollId);
   428→					hitsInx = 0;
   429→				}
   430→				if (size == 0 || (hits == null && rowData == null)) {
   431→					close(); 
   432→					ret = false;
   433→				}
   434→			} catch (Exception e) {
   435→				logger.error("", e);
   436→			}
   437→			return ret;
